): Effect.Effect =>
 Effect.Do.pipe(
 Effect.bind("startMillis", () => now),
 Effect.bind("result", () => self),
 Effect.bind("endMillis", () => now),
 Effect.let(
 "elapsed",
 // Calculate the elapsed time in milliseconds
 ({ startMillis, endMillis }) => endMillis - startMillis, …

