 // Fallback case for all other ages
 Match.orElse((user) => ${user.age} is too young),
)

console.log(match({ age: 20 }))
match({ age: 20 }) // => "Age: 20"

consol …

Match.not 函数允许你排除特定的值，同时匹配其余所有值。

示例（忽略某个特定的值）

// Create a matcher for string or number values
const match = Match.type ().pipe(
